class ComparisonResultsScreen extends StatefulWidget { const ComparisonResultsScreen({super.key, required this.controller, required this.product}); final FavourController controller; final Product product; @override State<ComparisonResultsScreen> createState() => _ComparisonResultsScreenState(); }
class _ComparisonResultsScreenState extends State<ComparisonResultsScreen> {
  late Product product = widget.product; bool loadingLive = false; List<Offer> liveOffers = const [];
  @override void initState() { super.initState(); _loadLivePrices(); }
  Future<void> _loadLivePrices() async {
    if (widget.controller.data.apiKey.trim().isEmpty) return;
    setState(() => loadingLive = true);
    try {
      final offers = await QuickCommerceApi().search(product, pincode: widget.controller.data.pincode, apiKey: widget.controller.data.apiKey);
      if (!mounted) return;
      liveOffers = offers;
      if (offers.isNotEmpty) {
        final existing = [...widget.controller.data.offers.where((o) => o.product.id != product.id), ...offers];
        await widget.controller.save(widget.controller.data.copyWith(offers: existing));
      }
      setState(() {});
    } finally { if (mounted) setState(() => loadingLive = false); }
  }
  List<Offer> get history { final all = [...widget.controller.data.offers.where((offer) => offer.product.id == product.id), ...liveOffers.where((offer) => offer.product.id == product.id)]; final seen = <String>{}; final result = <Offer>[]; for (final offer in all) { if (seen.add(offer.id)) result.add(offer); } result.sort((a, b) => b.checkedAt.compareTo(a.checkedAt)); return result; }
  Offer? latest(Retailer retailer) { final offers = history.where((offer) => offer.retailer == retailer).toList(); return offers.isEmpty ? null : offers.first; }
  Offer? get lowest { final offers = history.where((offer) => offer.available).toList()..sort((a, b) => a.knownTotal.compareTo(b.knownTotal)); return offers.isEmpty ? null : offers.first; }
  @override Widget build(BuildContext context) { final saved = widget.controller.data.favourites.any((item) => item.id == product.id); return Scaffold(appBar: AppBar(title: const Text('Compare'), actions: [IconButton(icon: Icon(saved ? Icons.bookmark : Icons.bookmark_outline), onPressed: _saveProduct), IconButton(icon: const Icon(Icons.add_shopping_cart), tooltip: 'Add to basket', onPressed: _addToBasket)]), floatingActionButton: FloatingActionButton.extended(onPressed: _importScreenshot, icon: const Icon(Icons.document_scanner_outlined), label: const Text('Import screenshot')), body: ListView(padding: const EdgeInsets.fromLTRB(16, 12, 16, 100), children: [InkWell(onTap: _editProduct, child: Card(child: Padding(padding: const EdgeInsets.all(16), child: Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(product.displayName, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), Text('${product.packLabel} • tap to edit')])), const Icon(Icons.edit_outlined)])))), const SizedBox(height: 12), if (loadingLive) const Card(child: Padding(padding: EdgeInsets.all(16), child: Row(children: [SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)), SizedBox(width: 12), Expanded(child: Text('Checking live prices across connected retailers…'))]))), const SizedBox(height: 12), if (lowest == null) const _UnavailableBanner() else Card(color: Theme.of(context).colorScheme.primaryContainer, child: Padding(padding: const EdgeInsets.all(16), child: Text('${lowest!.source == PriceSource.live ? 'Lowest live price' : 'Lowest recorded'}: ₹${lowest!.price.toStringAsFixed(2)} at ${lowest!.retailer.name} • ₹${lowest!.unitPrice.toStringAsFixed(2)}/${product.unit.normalizedLabel}', style: const TextStyle(fontWeight: FontWeight.bold)))), const SizedBox(height: 16), Text('Retailer offers', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), ...Retailer.values.map((retailer) => _OfferCard(retailer: retailer, offer: latest(retailer), isLowest: lowest != null && lowest?.id == latest(retailer)?.id, onOpen: () => _open(retailer), onRecord: () => _record(retailer, PriceSource.recorded)))])); }
  Future<void> _addToBasket() async { if (!widget.controller.data.basket.any((item) => item.product.id == product.id)) await widget.controller.save(widget.controller.data.copyWith(basket: [...widget.controller.data.basket, BasketItem(product: product)])); if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Added to Smart Basket.'))); }
  Future<void> _saveProduct() async { final saved = widget.controller.data.favourites.any((item) => item.id == product.id); await widget.controller.save(widget.controller.data.copyWith(favourites: saved ? widget.controller.data.favourites.where((item) => item.id != product.id).toList() : [...widget.controller.data.favourites, product])); }
  Future<void> _editProduct() async { final name = TextEditingController(text: product.name); final brand = TextEditingController(text: product.brand); final size = TextEditingController(text: product.packSize.toString()); final count = TextEditingController(text: product.packCount.toString()); var unit = product.unit; final changed = await showDialog<Product>(context: context, builder: (context) => AlertDialog(title: const Text('Confirm product'), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: name, decoration: const InputDecoration(labelText: 'Product name')), TextField(controller: brand, decoration: const InputDecoration(labelText: 'Brand')), TextField(controller: size, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Pack size')), TextField(controller: count, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Packs')), DropdownButtonFormField(value: unit, items: Unit.values.map((value) => DropdownMenuItem(value: value, child: Text(value.label))).toList(), onChanged: (value) => unit = value!)])), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { final parsedSize = double.tryParse(size.text); final parsedCount = int.tryParse(count.text); if (parsedSize == null || parsedCount == null || name.text.trim().isEmpty) return; Navigator.pop(context, Product(name: name.text.trim(), brand: brand.text.trim(), packSize: parsedSize, unit: unit, packCount: parsedCount)); }, child: const Text('Use product'))])); if (changed != null) setState(() => product = changed); }
  Future<void> _open(Retailer retailer) async { final query = Uri.encodeQueryComponent(product.displayName); final urls = {Retailer.blinkit: 'https://blinkit.com/s/?q=$query', Retailer.zepto: 'https://www.zeptonow.com/search?query=$query', Retailer.swiggyInstamart: 'https://www.swiggy.com/instamart/search?query=$query', Retailer.bigBasketNow: 'https://www.bigbasket.com/ps/?q=$query', Retailer.flipkartMinutes: 'https://www.flipkart.com/search?q=$query', Retailer.amazonNow: 'https://www.amazon.in/s?k=$query', Retailer.jioMart: 'https://www.jiomart.com/search/$query'}; await launchUrl(Uri.parse(urls[retailer]!), mode: LaunchMode.externalApplication); }
  Future<void> _importScreenshot() async { final image = await ImagePicker().pickImage(source: ImageSource.gallery); if (image == null || !mounted) return; try { final candidate = await OcrService().read(File(image.path)); if (!mounted) return; final retailer = await _chooseRetailer(); if (retailer == null || !mounted) return; await _record(retailer, PriceSource.screenshot, initialPrice: candidate.price, suggestion: candidate.product, rawText: candidate.rawText); } catch (_) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Could not read this screenshot. You can still record the price manually.'))); } }
  Future<Retailer?> _chooseRetailer() => showModalBottomSheet<Retailer>(context: context, builder: (_) => ListView(children: Retailer.values.map((retailer) => ListTile(title: Text(retailer.name), onTap: () => Navigator.pop(context, retailer))).toList()));
  Future<void> _record(Retailer retailer, PriceSource source, {double? initialPrice, Product? suggestion, String? rawText}) async { final price = TextEditingController(text: initialPrice?.toString() ?? ''); final result = await showDialog<Offer>(context: context, builder: (context) => AlertDialog(title: Text(source == PriceSource.screenshot ? 'Confirm screenshot price' : 'Record ${retailer.name} price'), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [if (source == PriceSource.screenshot) const Text('OCR is unverified. Confirm the product and price before saving.'), if (suggestion != null) Text('Detected: ${suggestion.displayName} ${suggestion.packLabel}'), TextField(controller: price, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Price', prefixText: '₹ ')), if (rawText != null) Text(rawText, maxLines: 4, overflow: TextOverflow.ellipsis, style: Theme.of(context).textTheme.bodySmall)])), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { final value = double.tryParse(price.text); if (value == null || value <= 0) return; Navigator.pop(context, Offer(id: DateTime.now().microsecondsSinceEpoch.toString(), product: product, retailer: retailer, price: value, checkedAt: DateTime.now(), available: true, source: source, sourceNote: source == PriceSource.screenshot ? 'User-confirmed OCR import' : 'User-recorded')); }, child: const Text('Confirm & save'))])); if (result != null) await widget.controller.addOffer(result); }
}
