class _OfferCard extends StatelessWidget { const _OfferCard({required this.retailer, required this.offer, required this.isLowest, required this.onOpen, required this.onRecord}); final Retailer retailer; final Offer? offer; final bool isLowest; final VoidCallback onOpen; final VoidCallback onRecord; @override Widget build(BuildContext context) => Card(margin: const EdgeInsets.only(bottom: 10), child: Padding(padding: const EdgeInsets.all(16), child: Column(children: [Row(children: [CircleAvatar(backgroundColor: retailer.color, child: Text(retailer.shortName, style: const TextStyle(color: Colors.white))), const SizedBox(width: 12), Expanded(child: Text(retailer.name, style: const TextStyle(fontWeight: FontWeight.bold))), if (isLowest && offer != null) const Chip(label: Text('LOWEST'))]), const SizedBox(height: 10), if (offer == null) const Align(alignment: Alignment.centerLeft, child: Text('Live price unavailable — connect a live source or use Record / Import screenshot.')), if (offer != null) Align(alignment: Alignment.centerLeft, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('₹${offer!.price.toStringAsFixed(2)} • ${offer!.product.packLabel}', style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.bold)), Text('₹${offer!.unitPrice.toStringAsFixed(2)} / ${offer!.product.unit.normalizedLabel} • ${offer!.available ? 'Available' : 'Unavailable'}'), Text('${offer!.source.label} • checked ${offer!.checkedAt.toLocal().toString().substring(0, 16)}'), if (offer!.knownFees > 0) Text('Known fees: ₹${offer!.knownFees.toStringAsFixed(2)}')])), Row(mainAxisAlignment: MainAxisAlignment.end, children: [TextButton(onPressed: onOpen, child: const Text('Open')), FilledButton.tonal(onPressed: onRecord, child: const Text('Record'))])]))); }
